-- September object printables. Safe to re-run: stable source keys prevent
-- duplicate catalog records, and relationship inserts are idempotent.
PRAGMA foreign_keys = ON;

INSERT OR IGNORE INTO categories (id, name, slug, description, sort_order, status) VALUES
  ('cat-bags-travel', 'Bags & Travel', 'bags-travel', 'Handbags, satchels, suitcases, and other everyday travel accessories to color.', 30, 'published'),
  ('cat-road-safety', 'Road Safety', 'road-safety', 'Traffic signs, signals, and road-safety objects to color and explore.', 31, 'published');

INSERT OR IGNORE INTO coloring_pages (
