) VALUES
  ('page-object-tagged-handbag', 'standard', 'Tagged Handbag Coloring Page', 'tagged-handbag', 'A roomy handbag with a hanging tag and sturdy shoulder straps.', '/coloring-pages/objects/tagged-handbag/line-art.webp', '/coloring-pages/objects/tagged-handbag/color.webp', '/coloring-pages/objects/tagged-handbag/line-art.webp', 'Tagged Handbag Coloring Page – Free Printable', 'Download a free printable tagged handbag coloring page with clean line art and a color reference.', 1, 'published', 300, 'standard:objects:tagged-handbag'),
