  ('page-object-travel-suitcase', 'standard', 'Travel Suitcase Coloring Page', 'travel-suitcase', 'A compact travel suitcase with reinforced corners, a handle, and a central clasp.', '/coloring-pages/objects/travel-suitcase/line-art.webp', '/coloring-pages/objects/travel-suitcase/color.webp', '/coloring-pages/objects/travel-suitcase/line-art.webp', 'Travel Suitcase Coloring Page – Free Printable', 'Download a free printable travel suitcase coloring page with clean line art and a color reference.', 0, 'published', 302, 'standard:objects:travel-suitcase'),
  ('page-object-leather-crossbody-bag', 'standard', 'Leather Crossbody Bag Coloring Page', 'leather-crossbody-bag', 'A detailed crossbody bag with a long strap, stitched panels, and a round clasp.', '/coloring-pages/objects/leather-crossbody-bag/line-art.webp', '/coloring-pages/objects/leather-crossbody-bag/color.webp', '/coloring-pages/objects/leather-crossbody-bag/line-art.webp', 'Leather Crossbody Bag Coloring Page – Free Printable', 'Download a free printable leather crossbody bag coloring page with clean line art and a color reference.', 0, 'published', 303, 'standard:objects:leather-crossbody-bag'),
  ('page-object-road-barricade', 'standard', 'Road Barricade Coloring Page', 'road-barricade', 'A striped road barricade with a warning light and folding support legs.', '/coloring-pages/objects/road-barricade/line-art.webp', '/coloring-pages/objects/road-barricade/color.webp', '/coloring-pages/objects/road-barricade/line-art.webp', 'Road Barricade Coloring Page – Free Printable', 'Download a free printable road barricade coloring page with clean line art and a color reference.', 1, 'published', 310, 'standard:objects:road-barricade'),
  ('page-object-merge-warning-signs', 'standard', 'Merge Warning Signs Coloring Page', 'merge-warning-signs', 'A pair of warning road signs showing lane-merging symbols.', '/coloring-pages/objects/merge-warning-signs/line-art.webp', '/coloring-pages/objects/merge-warning-signs/color.webp', '/coloring-pages/objects/merge-warning-signs/line-art.webp', 'Merge Warning Signs Coloring Page – Free Printable', 'Download a free printable merge warning signs coloring page with clean line art and a color reference.', 0, 'published', 311, 'standard:objects:merge-warning-signs'),
  ('page-object-stop-sign-and-cone', 'standard', 'Stop Sign and Traffic Cone Coloring Page', 'stop-sign-and-cone', 'A familiar stop sign standing beside a striped safety cone.', '/coloring-pages/objects/stop-sign-and-cone/line-art.webp', '/coloring-pages/objects/stop-sign-and-cone/color.webp', '/coloring-pages/objects/stop-sign-and-cone/line-art.webp', 'Stop Sign and Traffic Cone Coloring Page – Free Printable', 'Download a free printable stop sign and traffic cone coloring page with clean line art and a color reference.', 0, 'published', 312, 'standard:objects:stop-sign-and-cone'),
  ('page-object-sandbag-barrier', 'standard', 'Sandbag Barrier Coloring Page', 'sandbag-barrier', 'A sturdy filled sandbag used as a temporary safety barrier.', '/coloring-pages/objects/sandbag-barrier/line-art.webp', '/coloring-pages/objects/sandbag-barrier/color.webp', '/coloring-pages/objects/sandbag-barrier/line-art.webp', 'Sandbag Barrier Coloring Page – Free Printable', 'Download a free printable sandbag barrier coloring page with clean line art and a color reference.', 0, 'published', 313, 'standard:objects:sandbag-barrier'),
  ('page-object-parking-sign', 'standard', 'Parking Sign Coloring Page', 'parking-sign', 'A round parking sign on a tall post with a directional arrow.', '/coloring-pages/objects/parking-sign/line-art.webp', '/coloring-pages/objects/parking-sign/color.webp', '/coloring-pages/objects/parking-sign/line-art.webp', 'Parking Sign Coloring Page – Free Printable', 'Download a free printable parking sign coloring page with clean line art and a color reference.', 0, 'published', 314, 'standard:objects:parking-sign'),
  ('page-object-wooden-direction-sign', 'standard', 'Wooden Direction Sign Coloring Page', 'wooden-direction-sign', 'A weathered wooden signpost with arrows pointing in different directions.', '/coloring-pages/objects/wooden-direction-sign/line-art.webp', '/coloring-pages/objects/wooden-direction-sign/color.webp', '/coloring-pages/objects/wooden-direction-sign/line-art.webp', 'Wooden Direction Sign Coloring Page – Free Printable', 'Download a free printable wooden direction sign coloring page with clean line art and a color reference.', 0, 'published', 315, 'standard:objects:wooden-direction-sign'),
