  ('page-object-steering-wheel', 'standard', 'Steering Wheel Coloring Page', 'steering-wheel', 'A detailed steering wheel with padded grips and a central horn button.', '/coloring-pages/objects/steering-wheel/line-art.webp', '/coloring-pages/objects/steering-wheel/color.webp', '/coloring-pages/objects/steering-wheel/line-art.webp', 'Steering Wheel Coloring Page – Free Printable', 'Download a free printable steering wheel coloring page with clean line art and a color reference.', 0, 'published', 318, 'standard:objects:steering-wheel'),
  ('page-object-vehicle-horn', 'standard', 'Vehicle Horn Coloring Page', 'vehicle-horn', 'A classic vehicle horn with a flared speaker and sturdy base.', '/coloring-pages/objects/vehicle-horn/line-art.webp', '/coloring-pages/objects/vehicle-horn/color.webp', '/coloring-pages/objects/vehicle-horn/line-art.webp', 'Vehicle Horn Coloring Page – Free Printable', 'Download a free printable vehicle horn coloring page with clean line art and a color reference.', 0, 'published', 319, 'standard:objects:vehicle-horn'),
  ('page-object-traffic-light', 'standard', 'Traffic Light Coloring Page', 'traffic-light', 'A three-color traffic signal with red, amber, and green lenses.', '/coloring-pages/objects/traffic-light/line-art.webp', '/coloring-pages/objects/traffic-light/color.webp', '/coloring-pages/objects/traffic-light/line-art.webp', 'Traffic Light Coloring Page – Free Printable', 'Download a free printable traffic light coloring page with clean line art and a color reference.', 0, 'published', 320, 'standard:objects:traffic-light'),
  ('page-object-roadside-billboard', 'standard', 'Roadside Billboard Coloring Page', 'roadside-billboard', 'A blank roadside billboard ready for an original message or design.', '/coloring-pages/objects/roadside-billboard/line-art.webp', '/coloring-pages/objects/roadside-billboard/color.webp', '/coloring-pages/objects/roadside-billboard/line-art.webp', 'Roadside Billboard Coloring Page – Free Printable', 'Download a free printable roadside billboard coloring page with clean line art and a color reference.', 0, 'published', 321, 'standard:objects:roadside-billboard'),
  ('page-object-intersection-warning-sign', 'standard', 'Intersection Warning Sign Coloring Page', 'intersection-warning-sign', 'A road warning sign showing a four-way intersection ahead.', '/coloring-pages/objects/intersection-warning-sign/line-art.webp', '/coloring-pages/objects/intersection-warning-sign/color.webp', '/coloring-pages/objects/intersection-warning-sign/line-art.webp', 'Intersection Warning Sign Coloring Page – Free Printable', 'Download a free printable intersection warning sign coloring page with clean line art and a color reference.', 0, 'published', 322, 'standard:objects:intersection-warning-sign'),
  ('page-object-crossed-road-tools', 'standard', 'Crossed Road Tools Coloring Page', 'crossed-road-tools', 'A shovel and hoe crossed in front of a work-zone sign.', '/coloring-pages/objects/crossed-road-tools/line-art.webp', '/coloring-pages/objects/crossed-road-tools/color.webp', '/coloring-pages/objects/crossed-road-tools/line-art.webp', 'Crossed Road Tools Coloring Page – Free Printable', 'Download a free printable crossed road tools coloring page with clean line art and a color reference.', 0, 'published', 323, 'standard:objects:crossed-road-tools'),
  ('page-object-traffic-cone', 'standard', 'Traffic Cone Coloring Page', 'traffic-cone', 'A striped traffic cone on a wide square base.', '/coloring-pages/objects/traffic-cone/line-art.webp', '/coloring-pages/objects/traffic-cone/color.webp', '/coloring-pages/objects/traffic-cone/line-art.webp', 'Traffic Cone Coloring Page – Free Printable', 'Download a free printable traffic cone coloring page with clean line art and a color reference.', 0, 'published', 324, 'standard:objects:traffic-cone'),
  ('page-object-rubber-mallet', 'standard', 'Rubber Mallet Coloring Page', 'rubber-mallet', 'A sturdy rubber mallet with a long wooden handle.', '/coloring-pages/objects/rubber-mallet/line-art.webp', '/coloring-pages/objects/rubber-mallet/color.webp', '/coloring-pages/objects/rubber-mallet/line-art.webp', 'Rubber Mallet Coloring Page – Free Printable', 'Download a free printable rubber mallet coloring page with clean line art and a color reference.', 0, 'published', 325, 'standard:objects:rubber-mallet'),
  ('page-object-blank-road-sign', 'standard', 'Blank Road Sign Coloring Page', 'blank-road-sign', 'An empty road sign panel that invites children to invent their own symbol.', '/coloring-pages/objects/blank-road-sign/line-art.webp', '/coloring-pages/objects/blank-road-sign/color.webp', '/coloring-pages/objects/blank-road-sign/line-art.webp', 'Blank Road Sign Coloring Page – Free Printable', 'Download a free printable blank road sign coloring page with clean line art and a color reference.', 0, 'published', 326, 'standard:objects:blank-road-sign'),
