INSERT OR IGNORE INTO page_categories (page_id, category_id, is_primary)
SELECT id, 'cat-bags-travel', 1 FROM coloring_pages WHERE source_key LIKE 'standard:objects:%' AND slug IN ('tagged-handbag', 'leather-satchel', 'travel-suitcase', 'leather-crossbody-bag');

INSERT OR IGNORE INTO page_categories (page_id, category_id, is_primary)
SELECT id, 'cat-road-safety', 1 FROM coloring_pages WHERE source_key LIKE 'standard:objects:%' AND slug NOT IN ('tagged-handbag', 'leather-satchel', 'travel-suitcase', 'leather-crossbody-bag');
